RSpec.describe Timekeeping::LocalOwner do
  it "answers an update of another company's entry exactly like a missing id and changes nothing" do
    connection = ActiveRecord::Base.connection
    company_a = create(:company)
    company_b = create(:company)
    owner_a = create(:user)
    create(:employment, company: company_a, user: owner_a)
    owner_a.add_role("owner", company_a)
    owner_b = create(:user)
    create(:employment, company: company_b, user: owner_b)
    owner_b.add_role("owner", company_b)
    project_a = create(:project, client: create(:client, company: company_a))
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", generation: 3, handoff_step: nil)
    connection.execute(<<~SQL)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, note, bill_status,
                           review_status, source, created_at, updated_at)
      VALUES (93_001, #{company_a.id}, 1, #{project_a.id}, #{owner_a.id}, CURRENT_DATE, 60.0, 'company a', 'unbilled',
              'not_required', 'manual', NOW(), NOW())
    SQL
    counts = lambda do
      %w[entry_audits idempotency_records entry_outbox_items].map { |table| connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    end
    before_counts = counts.call
    actor = Timekeeping::LocalOwner::Actor.user(user_id: owner_b.id, role: "owner")
    update = lambda do |entry_id, key|
      described_class.call(operation: :update, company_id: company_b.id, generation: "3", actor:,
                           params: { "idempotency_key" => key, "entry_id" => entry_id,
                                     "body" => { "note" => "taken over" } })
    end

    # "An id from another company answers `not_found`, in the same shape as a missing id."
    foreign = update.call(93_001, "tenant-update-foreign")
    missing = update.call(93_999, "tenant-update-missing")

    expect(foreign.status).to eq(404)
    expect(foreign.status).to eq(missing.status)
    expect(foreign.body).to eq(missing.body)
    expect(connection.select_value("SELECT note FROM entries WHERE id = 93001")).to eq("company a")
    expect(connection.select_value("SELECT version FROM entries WHERE id = 93001").to_i).to eq(1)
    expect(counts.call).to eq(before_counts)
  end
end


